start.filterFormula:
AND( /* 1) Only run if there is any guardian identifying info present */ OR( NOT(ISBLANK({!$Record.Parent_Guardian_1_Email__c})), NOT(ISBLANK({!$Record.Parent_Guardian_1_Phone__c})), NOT(ISBLANK({!$Record.Parent_Guardian_1_First_Name__c})), NOT(ISBLANK({!$Record.Parent_Guardian_1_Last_Name__c})),
NOT(ISBLANK({!$Record.Parent_Guardian_2_Email__c})), NOT(ISBLANK({!$Record.Parent_Guardian_2_Phone__c})), NOT(ISBLANK({!$Record.Parent_Guardian_2_First_Name__c})), NOT(ISBLANK({!$Record.Parent_Guardian_2_Last_Name__c})), NOT(ISBLANK({!$Record.Parent_Guardian_2_Full_Name__c})) ),
/* 2) Run on create OR when guardian INPUT fields change */ OR( ISNEW(),
ISCHANGED({!$Record.Parent_Guardian_1_Email__c}), ISCHANGED({!$Record.Parent_Guardian_1_Phone__c}), ISCHANGED({!$Record.Parent_Guardian_1_First_Name__c}), ISCHANGED({!$Record.Parent_Guardian_1_Last_Name__c}), ISCHANGED({!$Record.Parent_Guardian_1_Relationship__c}),
ISCHANGED({!$Record.Parent_Guardian_2_Email__c}), ISCHANGED({!$Record.Parent_Guardian_2_Phone__c}), ISCHANGED({!$Record.Parent_Guardian_2_First_Name__c}), ISCHANGED({!$Record.Parent_Guardian_2_Last_Name__c}), ISCHANGED({!$Record.Parent_Guardian_2_Full_Name__c}), ISCHANGED({!$Record.Parent_Guardian_2_Relationship__c}) ),
/* 3) Guardrail: don't re-fire when only lookups are stamped */ NOT( OR( ISCHANGED({!$Record.Primary_Guardian__c}), ISCHANGED({!$Record.Secondary_Guardian__c}) ) ) )
